{"command": "cat > /tmp/create_json.py << 'EOF'
import json
import sys

with open('/tmp/new_kernel.txt', 'r') as f:
    kernel = f.read()

# Ensure kernel ends with newline
kernel = kernel.rstrip() + '\n'

# Build dictionary
output = {
    "vllm/lora/ops/triton_ops/fused_moe_lora_op.py": {
        "_fused_moe_lora_kernel": kernel
    }
}

with open('/prediction.json', 'w') as f:
    json.dump(output, f, indent=None)
EOF"}

